def f(I):
    H,W=len(I),len(I[0])
    out=[r[:] for r in I]
    pat=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=0 and I[r][c]!=5]
    rs=[p[0] for p in pat]; cs=[p[1] for p in pat]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    # anchor: the 5 inside the pattern bbox (demo shapes have one 5 cell); fallback: singletons
    cand=[p for p in pat if p[0]>=r0 and p[0]<=r1 and p[1]>=c0 and p[1]<=c1 and I[p[0]][p[1]]==5]
    ac=None
    if len(cand)==1: ac=cand[0]
    elif len(pat)-sum(1 for p in pat if p[1]==5 and r0<=p[0]<=r1 and c0<=p[1]<=c1)>=1:
        pass
    else:
        uniq={v for r,c,v in pat}
        for v in sorted(uniq):
            n=sum(1 for r,c,x in pat if x==v)
            if n==1 and all(x!=v for r,c,x in pat if True):
                for rr,cc,vvv in pat:
                    if vvv==v: ac=(rr,cc); break
                if ac: break
    ar,cc=ac
    strays=[(r,c) for r in range(H) for c in range(W) if I[r][c]==5 and (r<r0 or r>r1 or c<c0 or c>c1)]
    P=[(p[0]-ar,p[1]-cc,v) for p in pat if p[0]!=ar or p[1]!=cc or False]
    P=[(p[0],p[1],v) for p,v in [(p,p[2]) for p in pat] if p[0]!=ar or p[1]!=cc]
    for mr,mc in strays:
        T=(mr-ar,mc-cc)
        for pr,pc,v in P:
            r,cc2=pr+T[0],pc+T[1]
            if 0<=r<H and 0<=cc2<W:
                if I[r][cc2]!=5 or True: out[r][cc2]=v
    return out

